@js:
const FILTER_RULES = [
  /更新不易.+?看最新章节！/g,
  /更新不易.+?看最新无错章节！/g, 
  /更新不易.+?最新小说章节！/g,
  /速.?读.?谷/g, 
  /本章节未完.+?请订阅/g,
  /↑返回顶部↑/g,
  /[（(]本章.+?完[）)]/g,
  /^(?=.*[1-9])(?=.*章).+\n/,
]

for(let reg of FILTER_RULES){
	result = result.replace(reg, "")
}
result;
